insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('670a7986-20c6-5828-ae71-5845c13c4a02','aretha-franklin','Aretha Franklin',1942,2018,'1942-03-25',null,'Soul vocalist.','Grew up in Detroit as the daughter of a prominent Baptist minister, and had already recorded gospel albums as a teenager before signing with Atlantic Records in 1966. Her string of hits — including a 1967 recording of “Respect” that took on new meaning as a civil-rights and feminist anthem — carried her to 18 Grammy Awards and made her, in 1987, the first woman inducted into the Rock and Roll Hall of Fame. She died of pancreatic cancer in 2018, having sold more than 75 million records worldwide.','The best-selling female recording artist in American history, and the voice most identified with the word “Respect.”',98,true,'draft',true) on conflict (id) do nothing;
