insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('468fbec4-9b0e-5f01-9787-50f41f422286','rosa-parks','Rosa Parks',1913,2005,'1913-02-04',null,'Civil rights advocate.','A Montgomery seamstress and longtime NAACP chapter secretary, she had already investigated cases of racial violence for years before her refusal to give up a bus seat on December 1, 1955 triggered a 381-day boycott that helped dismantle Southern bus segregation. She later moved to Detroit, worked for decades as an aide to Congressman John Conyers, and co-founded an institute for youth leadership development. She received the Presidential Medal of Freedom in 1996 and died in 2005.','Her refusal to move seats on a Montgomery bus became one of the defining acts of the civil rights movement.',99,true,'draft',true) on conflict (id) do nothing;
