insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('832c7114-a4ba-5038-a420-5afac54cca76','edsel-ford','Edsel Ford',1893,1943,'1893-11-06',null,'Led Ford Motor Company.','The only child of Henry Ford, he became president of Ford Motor Company in 1919 and spent his tenure pushing the company past the aging Model T, overseeing the Model A, the Lincoln-Zephyr, and the creation of Ford''s Mercury division. During World War II he directed the Willow Run bomber plant toward a goal of one B-24 built per hour. An avid patron of the arts, he commissioned Diego Rivera''s Detroit Industry murals for the Detroit Institute of Arts and helped fund Richard Byrd''s Antarctic expeditions. He died in 1943 at age 49, and his nonvoting stock later formed the basis of the Ford Foundation.','Ran Ford Motor Company through the Model A and Willow Run''s wartime bomber line, while quietly building one of Detroit''s great art collections.',88,true,'draft',true) on conflict (id) do nothing;
