insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('e0bec093-e813-5985-bd05-8cd60a8413a7','john-dodge','John Dodge',1864,1920,'1864-10-25',null,'Helped establish Dodge.','Alongside his brother Horace, he ran a Detroit machine shop that became a critical parts supplier to the young Ford Motor Company, building Ford''s engines and transmissions for a decade while John also served as a Ford vice president. In 1914 the brothers broke away to build cars under their own name, launching Dodge Brothers Company and pairing his sales and business sense with Horace''s engineering. He died suddenly of pneumonia during the 1918 influenza pandemic while on a business trip to New York; the company his widow later sold for $146 million became the foundation of the modern Dodge brand.','Built Ford''s early engines before breaking away to found Dodge — and died of the same 1918 flu pandemic that killed millions worldwide.',85,false,'draft',true) on conflict (id) do nothing;
