insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('da14eb73-4a84-5361-82ca-8d7facd2b585','horace-dodge','Horace Dodge',1868,1920,'1868-05-17',null,'Helped establish Dodge.','The mechanically minded half of the Dodge brothers, he is credited with inventing an early dirt-proof ball bearing and ran the technical side of the machine shop that supplied engines and transmissions to Ford Motor Company for a decade. In 1914 he and John launched their own automobile under the Dodge Brothers name, and stock Ford later repurchased from the brothers for $25 million helped make both men wealthy. He and his wife Anna became major Detroit philanthropists, building the Rose Terrace mansion in Grosse Pointe and backing the Detroit Symphony Orchestra. He died in 1920, less than a year after his brother John.','The engineering half of the Dodge brothers, whose parts built Ford''s early cars before his own name went on the hood.',85,false,'draft',true) on conflict (id) do nothing;
