insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('94ba1a2f-cb0c-53cf-a955-5d8058d40b45','james-jamerson','James Jamerson',1938,1983,null,null,'Played bass for Motown.','Raised on Edisto Island, South Carolina before his family moved to Detroit, he became the uncredited bass player behind dozens of Motown''s biggest hits as a member of the studio band later known as the Funk Brothers. His inventive, syncopated bass lines — heard on records by the Supremes, the Temptations, and Marvin Gaye — appear on 23 number-one pop singles, a run exceeded only by Paul McCartney. He remained largely unrecognized by the public during his lifetime and died in 1983; he was inducted into the Rock and Roll Hall of Fame in 2000 and has since been ranked by multiple music publications as the greatest bassist in popular music history. Some sources, including Motown''s own records, list his birth year as 1936 rather than the 1938 given here, a discrepancy biographers have never fully resolved.','Played bass on more number-one hits than almost anyone in pop history, and Motown fans didn''t learn his name until decades later.',92,false,'draft',true) on conflict (id) do nothing;
