insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('8b1fdb9f-76fe-58be-92ed-1f5a792cd5ed','david-ruffin','David Ruffin',1941,1991,'1941-01-18',null,'Sang with the Temptations.','Raised in rural Mississippi, he became lead singer of the Temptations in 1964 and fronted the group''s best-known lineup through hits including “My Girl” and “Ain''t Too Proud to Beg,” his raspy, urgent tenor helping define the Motown sound of the era. Fired from the group in 1968, he built a solo career with hits like “My Whole World Ended,” and was inducted into the Rock and Roll Hall of Fame with the Temptations in 1989. He struggled with cocaine addiction for much of his life and died of an overdose in Philadelphia in 1991 at age 50.','The voice on “My Girl,” whose solo career never escaped the shadow of the group that fired him.',89,false,'draft',true) on conflict (id) do nothing;
