insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('2d951d78-04cb-536d-8f9f-ce193f21a5eb','levi-stubbs','Levi Stubbs',1936,2008,'1936-06-06',null,'Sang with the Four Tops.','The lead singer of the Four Tops for their entire five-decade career, he fronted the Motown group through more than a dozen hits and was inducted into the Rock and Roll Hall of Fame in 1990. Despite offers to go solo, he stayed with the same three bandmates his whole career, and expanded into voice acting, playing the man-eating plant Audrey II in the 1986 film Little Shop of Horrors. He gave his final concert performance at the Four Tops'' 50th-anniversary show in Detroit in 2004, and died of cancer in 2008.','Turned down solo stardom to stay with the Four Tops for fifty years — and gave a carnivorous plant its singing voice.',89,false,'draft',true) on conflict (id) do nothing;
