insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('7877fd69-c3db-5471-bbf8-1aec34a0a96d','ed-killian','Ed Killian',1876,1928,'1876-11-12',null,'Pitched in major-league baseball.','A left-handed pitcher nicknamed “Twilight Ed” for his knack of stretching games into extra innings before darkness called them, he anchored the Detroit Tigers'' pitching staff through three consecutive American League pennants from 1907 to 1909. He once lost a 15-inning scoreless duel to Cy Young by a single run in 1904, and at one stretch went 1,001 innings without allowing a home run — still among the longest such streaks in major-league history. He finished his career with a 103–78 record and a 2.38 ERA, and died in 1928.','Went over 1,000 innings without giving up a home run while helping pitch the Tigers to three straight pennants.',65,false,'draft',true) on conflict (id) do nothing;
