insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('9df5ce48-8ae3-5d08-9294-65a19c3f3218','roy-chapin','Roy D. Chapin',1880,1936,'1880-02-23',null,'Automotive leader and commerce secretary.','A Lansing native who co-founded Hudson Motor Car Company in 1908, he built it into one of the most profitable independent automakers of the 1920s, and in 1922 his Hudson subsidiary Essex introduced the first affordable mass-produced enclosed car, changing what buyers expected from an ordinary automobile. He briefly left the industry to serve as U.S. Secretary of Commerce under President Hoover from 1932 to 1933, then returned to lead Hudson through the early Depression years until his death in 1936. He was also a longtime advocate for the Lincoln Highway and better American roads.','Built Hudson into a major automaker, put the first affordable enclosed car on the road, and briefly ran the U.S. Commerce Department.',76,false,'draft',true) on conflict (id) do nothing;
