insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('7bf0d432-70b0-5b5d-8796-ff38dda5d0c4','george-holley','George M. Holley Sr.',1878,1963,null,null,'Designed automotive technology.','As teenagers in Bradford, Pennsylvania, George Holley and his brother Earl built a three-wheeled, one-cylinder “Runabout” capable of 30 miles per hour, and by 1902 were selling a four-wheeled car called the Holley Motorette. Their carburetor design caught Henry Ford''s attention, and the Model T contract that followed made Holley Carburetor Company, formally established in Detroit in 1905, one of Ford''s key suppliers; by 1913 Holley carburetors equipped more than half of the cars leaving American factories. George later served as company president and sat on the boards of several aviation firms during the 1920s and 1930s. He died in 1963.','His carburetor design ended up under the hood of most American cars built by the 1910s.',72,false,'draft',true) on conflict (id) do nothing;
