insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('27713897-8883-537c-be67-63c3703ee029','clara-arthur','Clara Arthur',1858,1929,'1858-10-25',null,'Advocated for women’s voting rights.','Born in Saint John, New Brunswick, she co-founded the Michigan Equal Suffrage Association in 1885 and led it as president from 1906 through the final push for the vote. She first won a partial victory, amending Michigan''s constitution to let women vote on tax and bond questions, before leading the statewide campaign that secured full women''s suffrage in Michigan in 1918 — two years ahead of the federal 19th Amendment. She also served on the National Child Labor Committee, and died in 1929.','Won women in Michigan the right to vote two years before the 19th Amendment made it national.',72,false,'draft',true) on conflict (id) do nothing;
