insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('02e37930-2dcb-5628-a702-7c717071e7e5','coleman-young','Coleman Young',1918,1997,'1918-05-24',null,'Led Detroit as mayor.','Born in Alabama and raised in Detroit, he became the city''s first Black mayor in 1974 after a campaign centered on police reform, and went on to serve an unprecedented five terms. He disbanded the controversial STRESS police unit and pushed affirmative-action hiring that raised Black representation on the police force from under 10 percent to more than half by the early 1990s, while backing major downtown projects like the Renaissance Center and the Detroit People Mover. His twenty years in office also coincided with a loss of roughly 500,000 residents from the city, a decline driven by white flight and the collapse of manufacturing jobs that he spent his tenure fighting. He died in 1997, four years after leaving office.','Detroit''s first Black mayor, in office for twenty years spanning the city''s most dramatic population decline.',90,false,'draft',true) on conflict (id) do nothing;
