insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('7e5ddc37-8cd8-51b8-827e-4d46e4928111','russell-alger','Russell A. Alger',1836,1907,'1836-02-27',null,'Served as Michigan governor.','An Ohio-born lawyer who moved to Michigan and made a fortune in Upper Peninsula lumber, he had already fought in 66 Civil War engagements and risen to brevet major general by the time he was elected Michigan''s governor in 1884. He later served as U.S. Secretary of War under President McKinley from 1897 to 1899, a tenure defined by criticism over the military''s poor preparation for the Spanish-American War, and finished his career appointed to the U.S. Senate, where he chaired the Pacific Railroads committee until his death in 1907.','Went from Civil War general to Michigan governor to a wartime cabinet post that ended in controversy over an unprepared Army.',78,false,'draft',true) on conflict (id) do nothing;
