insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('9dbb7377-b309-5293-b64d-94fdf1120b37','lewis-cass','Lewis Cass',1782,1866,'1782-10-09',null,'Governed Michigan Territory.','A New Hampshire-born lawyer who came west as territorial governor of Michigan in 1813, he spent nearly two decades negotiating treaties that opened Native American land to American settlement, then went on to serve as Secretary of War under Andrew Jackson, where he became a central figure in carrying out the era''s Indian removal policy. He later represented Michigan in the U.S. Senate across two separate stretches, won the Democratic presidential nomination in 1848 (losing to Zachary Taylor after his position on slavery''s expansion split the party), and served as Secretary of State under James Buchanan before resigning over the government''s response to Southern secession. He died in Detroit in 1866.','Governed Michigan Territory, ran for president in 1848, and helped carry out the federal policy that forced Native nations off their land.',78,false,'draft',true) on conflict (id) do nothing;
