insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('ca959d4e-a59a-5f01-9f9a-b8e7a13e4fab','zachariah-chandler','Zachariah Chandler',1813,1879,'1813-12-10',null,'Represented Michigan in the Senate.','A New Hampshire native who built a fortune in Detroit dry goods before entering politics, he became a founding force in Michigan''s Republican Party and a leading voice of its antislavery wing. He represented Michigan in the U.S. Senate for four terms starting in 1857, chairing the Commerce Committee and pushing hard against secession in the years before the Civil War, then served as Secretary of the Interior under President Grant, where he moved aggressively against corrupt federal agents. He chaired the Republican National Committee during Rutherford B. Hayes''s contested 1876 campaign, and died in 1879, the morning after delivering a political speech in Chicago.','Helped found Michigan''s Republican Party, then ran Hayes''s national campaign a century before dying mid-comeback in 1879.',76,false,'draft',true) on conflict (id) do nothing;
