insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('f31d3b3c-33c0-5cd8-9997-5ebec413eceb','philip-cooke','Philip St. George Cooke',1809,1895,'1809-06-13',null,'Served as a Civil War general.','A Virginia-born West Point graduate, he spent nearly fifty years as a U.S. cavalry officer and is remembered as one of the founding figures of the American mounted service. During the Mexican-American War he led the Mormon Battalion on a march that carved out what became known as Cooke''s Wagon Road, later a key route for California-bound migrants, and he later wrote an influential, if controversial, cavalry tactics manual. Though born in the South, he stayed loyal to the Union during the Civil War even as his own son joined the Confederate army and his son-in-law became the famous Confederate cavalry commander J.E.B. Stuart. He died in 1895.','A Virginia-born cavalry officer who stayed loyal to the Union even as his own son-in-law became a famous Confederate general.',68,false,'draft',true) on conflict (id) do nothing;
