insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('d7c76126-175f-57ae-b496-99c1a87203ea','william-ferguson','William Webb Ferguson',1857,1910,'1857-05-22',null,'Broke a racial barrier in Michigan’s legislature.','The first Black graduate of a Detroit public high school, he built a successful printing business before winning a landmark 1890 discrimination lawsuit after being denied restaurant service — a case decided in his favor by the Michigan Supreme Court. Three years later he became the first African American elected to the Michigan House of Representatives, representing a Wayne County district as a Republican from 1893 to 1896. He died in Detroit in 1910.','Won a Michigan Supreme Court discrimination case, then became the first Black legislator elected to the state House.',80,false,'draft',true) on conflict (id) do nothing;
