insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('4eba5497-b74f-562a-95ab-f6b23c02c451','harry-guy','Harry P. Guy',1870,1950,'1870-07-17',null,'Composed ragtime music.','An Ohio-born composer who studied under Victor Herbert before settling in Detroit in 1895, he wrote popular music for local publishers and produced orchestral arrangements for both the University of Michigan and University of Detroit. His 1898 composition “Chicken Chowder” became a ragtime standard still performed today, but commercial success never followed him personally, and he spent his later years largely forgotten and living in poverty. He died in 1950; his grave went unmarked until a historical marker was placed there in 2003.','Wrote a ragtime standard still played today, then died in obscurity and poverty.',70,false,'draft',true) on conflict (id) do nothing;
