insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('8f843cd2-a0db-5874-b795-6ac47559f0a4','sam-thompson','Sam Thompson',1860,1922,'1860-03-05',null,'Baseball Hall of Fame outfielder.','An Indiana-born outfielder, he won the National League batting title in 1887 with a .372 average and set a major-league record with 166 RBIs in just 127 games — a mark that still stands relative to games played. Two years later he became the first player to combine 20 home runs and 20 stolen bases in a single season, over a career split mostly between the Detroit Wolverines and Philadelphia Phillies with a brief return to the Tigers in 1906. He finished with a career .331 batting average and 1,988 hits, and was inducted into the Baseball Hall of Fame by the Veterans Committee in 1974, more than fifty years after his death in 1922.','Set a still-standing RBI-to-games record in 1887 — over half a century before the Hall of Fame got around to inducting him.',85,false,'draft',true) on conflict (id) do nothing;
