insert into public.people (id,slug,name,birth_year,death_year,birth_date,death_date,short_description,biography,why_interesting,dead_score,is_featured,status,is_fixture) values ('ec9e5e65-0032-5470-aafa-a6f2e5d5296d','martha-jean-steinberg','Martha Jean Steinberg',1930,2000,'1930-09-09',null,'Worked in radio.','Born in Memphis, she broke into radio in 1954 after winning a contest at WDIA, becoming one of the first Black female disc jockeys in the country and earning the nickname “the Queen.” After moving to Detroit in 1963, she built a following at WJLB, and during the unrest of July 1967 persuaded the station to drop its regular programming — an intervention some credit with helping calm the city. She was later ordained as a minister, closing her broadcasts with “God loves you and I love you,” and in 1982 bought her own station, WQBH, which she ran until her death in 2000.','Talked a Detroit radio station into changing its programming during the 1967 unrest — then bought her own station years later.',75,false,'draft',true) on conflict (id) do nothing;
